<?php
 namespace Pterodactyl\Services\Dezerx; use Illuminate\Support\Str; use Pterodactyl\Rules\Username; class Registration { public static function enabled(): bool { return Theme::config()['auth.register'] === true; } public static function asksForNames(): bool { return Theme::config()['auth.registerNames'] === true; } public static function terms(): ?string { $url = (string) Theme::config()['auth.registerTerms']; return $url === '' ? null : $url; } public static function domains(): array { $raw = (string) Theme::config()['auth.registerDomains']; if (trim($raw) === '') { return []; } $out = []; foreach (preg_split('/[,\s]+/', $raw) ?: [] as $entry) { $domain = ltrim(Str::lower(trim($entry)), '@'); if ($domain !== '' && !in_array($domain, $out, true)) { $out[] = $domain; } } return $out; } public static function allows(string $email): bool { $domains = self::domains(); if ($domains === []) { return true; } $at = strrpos($email, '@'); if ($at === false) { return false; } return in_array(Str::lower(substr($email, $at + 1)), $domains, true); } public static function rules(): array { $rules = [ 'username' => ['required', 'string', 'between:3,191', 'unique:users,username', new Username()], 'email' => ['required', 'string', 'email:strict', 'between:1,191', 'unique:users,email'], 'password' => ['required', 'string', 'min:8', 'confirmed'], ]; if (self::asksForNames()) { $rules['name_first'] = ['required', 'string', 'between:1,191']; $rules['name_last'] = ['required', 'string', 'between:1,191']; } if (self::terms() !== null) { $rules['terms'] = ['accepted']; } return $rules; } public static function messages(): array { return [ 'terms.accepted' => 'The terms have to be accepted before an account can be made.', 'email.unique' => 'There is already an account using that email address.', 'username.unique' => 'That username is taken.', ]; } } 